```javascript
function getCompanyData(companyName) {
  const searchEngineId = "YOUR_CSE_ID"; // Replace with your CSE ID
  const apiKey = "YOUR_API_KEY"; // Replace with your API key
  const domainQuery = `site:*.com ${companyName} website`;
  const linkedInQuery = `${companyName} LinkedIn`;
  const marketingQuery = `${companyName} Head of Marketing`;

  // Get domain
  const domainResult = searchCSE(domainQuery, searchEngineId, apiKey);
  const domain = domainResult ? extractDomain(domainResult[0].link) : "";

  // Get LinkedIn profile
  const linkedInResult = searchCSE(linkedInQuery, searchEngineId, apiKey);
  const linkedInUrl = linkedInResult ? linkedInResult[0].link : "";

  // Get marketing head name
  const marketingResult = searchCSE(marketingQuery, searchEngineId, apiKey);
  const marketingName = marketingResult ? extractName(marketingResult[0].link) : "";

  return [domain, marketingName, linkedInUrl];
}

function searchCSE(query, searchEngineId, apiKey) {
  const url = `https://www.googleapis.com/customsearch/v1?key=${apiKey}&cx=${searchEngineId}&q=${encodeURIComponent(query)}`;
  const response = UrlFetchApp.fetch(url);
  const json = JSON.parse(response.getContentText());
  return json.items || [];
}

function extractDomain(url) {
  if (!url) return "";
  const domainMatch = url.match(/https?:\/\/([^\/]+)/);
  return domainMatch ? domainMatch[1] : "";
}

function extractName(url) {
  if (!url) return "";
  // Example: Parse LinkedIn profile name from URL
  const nameMatch = url.match(/linkedin.com/in\/([^\/]+)/);
  return nameMatch ? nameMatch[1].replace(/-/g, " ") : "";
}
```

